?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=installer_e($packageName)?> installer</title><style>body{margin:0;background:#080b12;color:#f7f8fb;font:15px system-ui,sans-serif}.wrap{max-width:850px;margin:40px auto;padding:24px}.panel{background:#121923;border:1px solid #2b3546;border-radius:14px;padding:24px;box-shadow:0 18px 50px #0005}h1{margin-top:0}h2{font-size:18px;margin-top:28px;color:#c39cff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:grid;gap:6px;color:#b9c0cc}input,select{padding:12px;border-radius:8px;border:1px solid #354154;background:#0d141e;color:#fff}button{margin-top:22px;width:100%;padding:14px;border:0;border-radius:8px;background:#803fff;color:#fff;font-weight:800}.notice{padding:12px;border-radius:8px;background:#17243b;margin:12px 0}.error{background:#391924;color:#ffb9c3}.success{background:#153b2a;color:#a9f2c6}small{color:#8994a6}.success-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.success-actions a{display:inline-block;padding:10px 16px;border-radius:8px;background:#803fff;color:#fff;text-decoration:none;font-weight:800}.success-actions a+ a{background:#1b2940}@media(max-width:650px){.grid{grid-template-columns:1fr}.success-actions a{flex:1;text-align:center}}</style></head><body><main class="wrap"><section class="panel"><h1><?=installer_e($packageName)?> installer</h1><p>Configure a standard PHP/MySQL digital record shop. Existing configurations are never overwritten.</p><?php foreach($errors as $error):?><div class="notice error"><?=installer_e($error)?></div><?php endforeach;?><?php if($success):?><div class="notice success"><strong>Installation complete</strong><br><?=installer_e($success)?><div class="success-actions"><a href="index.php">Go to home</a><a href="login.php">Log in</a></div></div><?php elseif(!is_readable($configPath)):?><form method="post"><input type="hidden" name="installer_token" value="<?=installer_e(installer_token())?>"><h2>Application</h2><div class="grid"><label>Application name<input name="app_name" value="<?=installer_e($defaults['app_name'])?>" required></label><label>Base URL<input type="url" name="base_url" value="<?=installer_e($defaults['base_url'])?>" required></label><label>Timezone<select name="timezone" required><?php foreach($timezoneOptions as $timezoneValue=>$timezoneLabel):?><option value="<?=installer_e($timezoneValue)?>" <?=$defaults['timezone']===$timezoneValue?'selected':''?>><?=installer_e($timezoneLabel)?></option><?php endforeach;?></select><small>Choose the timezone used for dates, reports, scheduled tasks and email timing.</small></label><label>Private application storage<select name="private_mode"><option value="external" <?=$privateModeDefault==='external'?'selected':''?> <?=$privateModeDefault==='external'?'':'disabled'?>>Outside web root (recommended)</option><option value="internal" <?=$privateModeDefault==='internal'?'selected':''?> <?=$internalWritable?'':'disabled'?>>Inside web root (protected directory)</option></select><small>Use outside web root when the host allows it. The inside option is for shared hosting and requires server access rules to block the private directory.</small></label><label>Scheduler<select name="scheduler"><option value="cron">Normal cron</option><option value="plesk">Plesk Scheduled Task</option><option value="webcron">External web cron URL</option><option value="lazy">Website traffic fallback</option></select></label></div><h2>Database</h2><div class="grid"><label>Host<input name="db_host" value="<?=installer_e($defaults['db_host'])?>" required></label><label>Port<input type="number" name="db_port" value="<?=installer_e($defaults['db_port'])?>" required></label><label>Database name<input name="db_name" value="<?=installer_e($defaults['db_name'])?>" required></label><label>Database user<input name="db_user" value="<?=installer_e($defaults['db_user'])?>" required></label><label>Database password<input type="password" name="db_pass"></label></div><h2>Administrator</h2><div class="grid"><label>Name<input name="admin_name" value="<?=installer_e($defaults['admin_name'])?>" required></label><label>Email<input type="email" name="admin_email" value="<?=installer_e($defaults['admin_email'])?>" required></label><label>Password<input type="password" name="admin_password" minlength="12" required></label><label>Confirm password<input type="password" name="admin_password_confirm" minlength="12" required></label></div><button>Install application</button></form><?php else:?><div class="notice">The installer is disabled because a configuration already exists.</div><?php endif;?></section></main></body></html>
